		if (!input || input.length === 0) return true;
		const left = input[0];
		if (!left) return true;
		// Soft limiting (tanh) keeps loud input smooth instead of hard-clipping.
		const g = this.gain;
		const gated = [];
		for (let i = 0; i < left.length; i++) {
			const s = left[i] * g;
			gated.push(Math.tanh(s));
		}
